INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:1]%' ORDER BY id LIMIT 1),'{"title": "Visitor Check-in", "glossary": {"visitors": "khách đến thăm", "entrance": "lối vào", "register": "sổ đăng ký", "badge": "thẻ", "advance": "trước; sớm"}, "lines": [{"en": "To: All visitors · Subject: Entering the West Office", "vi": "Gửi: Khách đến thăm · Chủ đề: Vào văn phòng phía Tây"}, {"en": "The reception desk [135] at 8:30 a.m. every weekday. Please use the main entrance.", "vi": "Quầy lễ tân mở cửa lúc 8 giờ 30 mỗi ngày trong tuần. Vui lòng dùng lối vào chính."}, {"en": "All visitors must sign [136] names in the register. A receptionist will then issue a badge.", "vi": "Mọi khách phải ghi tên của mình vào sổ. Sau đó lễ tân sẽ cấp thẻ."}, {"en": "Please wear the badge [137] your visit. Return it before leaving the building.", "vi": "Vui lòng đeo thẻ trong suốt chuyến thăm. Trả lại trước khi rời tòa nhà."}, {"en": "[138] This will help us prepare the correct number of badges.", "vi": "Vui lòng báo trước cho chúng tôi có bao nhiêu người sẽ đến. Việc này giúp chuẩn bị đúng số thẻ."}], "content_key": "n11-reading-expansion-20261116-p6-l1"}',2 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:1]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p6-l1%');
