INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:2]%' ORDER BY id LIMIT 1),'{"title": "Restaurant Booking", "glossary": {"reservation": "đặt chỗ", "allergies": "dị ứng", "deposit": "tiền đặt cọc", "deducted": "được khấu trừ", "bill": "hóa đơn"}, "lines": [{"en": "From: Elm Restaurant · Subject: Your team dinner", "vi": "Từ: Nhà hàng Elm · Chủ đề: Bữa tối của nhóm bạn"}, {"en": "We are pleased [135] your reservation for twelve people on Friday at 7 p.m.", "vi": "Chúng tôi vui mừng xác nhận đặt bàn cho mười hai người vào thứ Sáu lúc 7 giờ tối."}, {"en": "Your table is in the garden room, which is [136] than the main dining area.", "vi": "Bàn của bạn ở phòng vườn, yên tĩnh hơn khu ăn chính."}, {"en": "Please inform us [137] any food allergies by Thursday afternoon. Our chef can adjust the menu.", "vi": "Vui lòng thông báo cho chúng tôi về dị ứng thực phẩm trước chiều thứ Năm. Đầu bếp có thể điều chỉnh thực đơn."}, {"en": "[138] The amount will be deducted from your final bill.", "vi": "Cần đặt cọc 50 đô la để giữ phòng. Khoản này sẽ được trừ vào hóa đơn cuối."}], "content_key": "n11-reading-expansion-20261116-p6-l2"}',2 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:2]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p6-l2%');
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:2]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:2]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p6-l2%' ORDER BY id LIMIT 1),'Chọn đáp án cho chỗ trống [135]','{"options_vi": {"A": "xác nhận", "B": "đang xác nhận", "C": "để xác nhận (to V)", "D": "đã xác nhận"}, "explanation": "Be pleased to do something là cấu trúc diễn tả vui mừng làm việc gì. Cần to confirm sau pleased."}',135 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:2]%' ORDER BY id LIMIT 1) AND question_text='Chọn đáp án cho chỗ trống [135]' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:2]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p6-l2%' ORDER BY id LIMIT 1));
