INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:3]%' ORDER BY id LIMIT 1),'{"title": "Online Expense Claims", "glossary": {"expenses": "chi phí", "receipts": "biên lai", "approved": "được duyệt", "claim": "yêu cầu thanh toán", "demonstration": "buổi hướng dẫn"}, "lines": [{"en": "MEMO · Subject: New expense system", "vi": "BẢN GHI NHỚ · Chủ đề: Hệ thống chi phí mới"}, {"en": "Starting next month, staff [135] travel expenses through the employee portal rather than on paper.", "vi": "Từ tháng sau, nhân viên sẽ nộp chi phí công tác qua cổng nhân viên thay vì trên giấy."}, {"en": "Receipts must be uploaded [136] a claim can be approved. Keep the originals until payment has been received.", "vi": "Phải tải biên lai lên trước khi yêu cầu được duyệt. Giữ bản gốc đến khi nhận thanh toán."}, {"en": "The portal automatically checks whether the information is [137]. Missing details will be highlighted.", "vi": "Cổng tự động kiểm tra thông tin có đầy đủ hay không. Chi tiết còn thiếu sẽ được tô sáng."}, {"en": "[138] A recording will also be available for anyone unable to attend.", "vi": "Một buổi hướng dẫn trực tiếp sẽ diễn ra trực tuyến vào thứ Tư. Bản ghi cũng sẽ có cho người không tham dự được."}], "content_key": "n11-reading-expansion-20261116-p6-l3"}',2 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:3]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p6-l3%');
