INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:4]%' ORDER BY id LIMIT 1),'{"title": "Museum Volunteer Program", "glossary": {"volunteers": "tình nguyện viên", "curator": "người phụ trách bảo tàng", "collection": "bộ sưu tập", "consistent": "nhất quán", "exhibition": "triển lãm"}, "lines": [{"en": "To: Volunteer coordinators · Subject: Exhibition support", "vi": "Gửi: Điều phối viên tình nguyện · Chủ đề: Hỗ trợ triển lãm"}, {"en": "Applications [135] after August 1 will be considered for the winter exhibition only.", "vi": "Đơn nhận sau ngày 1 tháng 8 sẽ chỉ được xét cho triển lãm mùa đông."}, {"en": "All volunteers are required to attend training, [136] their previous experience.", "vi": "Mọi tình nguyện viên phải dự đào tạo, bất kể kinh nghiệm trước đây."}, {"en": "The curator has asked that each volunteer [137] a short introduction to the collection.", "vi": "Người phụ trách yêu cầu mỗi tình nguyện viên chuẩn bị phần giới thiệu ngắn về bộ sưu tập."}, {"en": "[138] This ensures that visitors receive accurate and consistent information.", "vi": "Tất cả phần giới thiệu sẽ được người phụ trách xem lại trước khi sử dụng. Việc này bảo đảm khách nhận thông tin chính xác và nhất quán."}], "content_key": "n11-reading-expansion-20261116-p6-l4"}',2 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:4]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p6-l4%');
