INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1),'{"title": "Contingency Planning", "glossary": {"migration": "việc chuyển đổi hệ thống", "backup": "bản sao lưu", "verification": "việc xác minh", "recovery": "khôi phục", "interval": "khoảng thời gian"}, "lines": [{"en": "To: Project leads · Subject: Data center relocation", "vi": "Gửi: Trưởng dự án · Chủ đề: Di chuyển trung tâm dữ liệu"}, {"en": "The migration may proceed [135] the backup system has passed all verification tests.", "vi": "Việc chuyển đổi có thể tiến hành với điều kiện hệ thống sao lưu đã qua mọi kiểm tra xác minh."}, {"en": "Had the backup failed, the team [136] the migration until a replacement was available.", "vi": "Nếu bản sao lưu bị lỗi, nhóm đã phải hoãn chuyển đổi đến khi có bản thay thế."}, {"en": "The revised schedule, [137] details were circulated yesterday, includes an additional recovery window.", "vi": "Lịch sửa đổi, có chi tiết đã được gửi hôm qua, gồm thêm một khoảng thời gian khôi phục."}, {"en": "[138] Consequently, no customer transactions will be processed during that interval.", "vi": "Hệ thống đặt hàng sẽ được tạm dừng trong khoảng thời gian khôi phục này. Vì vậy, không giao dịch khách hàng nào được xử lý trong khoảng đó."}], "content_key": "n11-reading-expansion-20261116-p6-l5"}',2 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p6-l5%');
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p6-l5%' ORDER BY id LIMIT 1),'Chọn đáp án cho chỗ trống [135]','{"options_vi": {"A": "mặc dù (+ danh từ)", "B": "với điều kiện là", "C": "do (+ danh từ)", "D": "bất kể"}, "explanation": "Provided that dẫn mệnh đề điều kiện hệ thống đã qua kiểm tra. Các phương án còn lại là giới từ không đi trực tiếp với mệnh đề."}',135 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1) AND question_text='Chọn đáp án cho chỗ trống [135]' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p6-l5%' ORDER BY id LIMIT 1));
