INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1),'{"title": "Fitness Center Update", "glossary": {"pool": "hồ bơi", "cleaning": "việc vệ sinh", "replacement": "thay thế; học bù", "charge": "khoản phí", "reserve": "giữ chỗ"}, "documents": [{"title": "Pool maintenance notice", "title_vi": "Thông báo bảo trì hồ bơi", "lines": [{"en": "The indoor pool will be closed on Tuesday, July 8, for cleaning. It will reopen at 6 a.m. on Wednesday. The gym and tennis courts will remain open as usual.", "vi": "Hồ bơi trong nhà đóng cửa thứ Ba ngày 8 tháng 7 để vệ sinh. Hồ mở lại lúc 6 giờ sáng thứ Tư. Phòng tập và sân quần vợt vẫn mở bình thường."}, {"en": "Members with Tuesday swimming lessons may attend a replacement lesson on Friday at no additional charge. Please contact reception to reserve a place.", "vi": "Thành viên học bơi thứ Ba có thể dự buổi bù vào thứ Sáu không mất thêm phí. Vui lòng liên hệ lễ tân để giữ chỗ."}]}], "content_key": "n11-reading-expansion-20261116-p7-l1"}',2 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l1%');
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l1%' ORDER BY id LIMIT 1),'Why will the pool be closed?','{"translation": "Vì sao hồ bơi đóng cửa?", "options_vi": {"A": "Để thi đấu riêng", "B": "Để vệ sinh cơ sở", "C": "Để đào tạo nhân viên", "D": "Vì hết hạn thành viên"}, "evidence": "The indoor pool will be closed on Tuesday, July 8, for cleaning.", "explanation": "Thông báo nêu rõ mục đích là vệ sinh, không phải thi đấu, đào tạo hoặc vấn đề tư cách thành viên.", "analysis": {"A": "Không phù hợp với dẫn chứng: Để thi đấu riêng. Thông báo nêu rõ mục đích là vệ sinh, không phải thi đấu, đào tạo hoặc vấn đề tư cách thành viên.", "B": "Đúng. Thông báo nêu rõ mục đích là vệ sinh, không phải thi đấu, đào tạo hoặc vấn đề tư cách thành viên.", "C": "Không phù hợp với dẫn chứng: Để đào tạo nhân viên. Thông báo nêu rõ mục đích là vệ sinh, không phải thi đấu, đào tạo hoặc vấn đề tư cách thành viên.", "D": "Không phù hợp với dẫn chứng: Vì hết hạn thành viên. Thông báo nêu rõ mục đích là vệ sinh, không phải thi đấu, đào tạo hoặc vấn đề tư cách thành viên."}}',160 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND question_text='Why will the pool be closed?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l1%' ORDER BY id LIMIT 1));
