INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l1%' ORDER BY id LIMIT 1),'What is offered to Tuesday swimming students?','{"translation": "Học viên bơi thứ Ba được đề nghị gì?", "options_vi": {"A": "Buổi học bù miễn phí", "B": "Thẻ thành viên mới", "C": "Hoàn phí cả năm", "D": "Buổi quần vợt riêng"}, "evidence": "Members with Tuesday swimming lessons may attend a replacement lesson on Friday at no additional charge.", "explanation": "No additional charge nghĩa là không tính thêm phí cho buổi bù thứ Sáu, không phải hoàn phí năm hay học môn khác.", "analysis": {"A": "Đúng. No additional charge nghĩa là không tính thêm phí cho buổi bù thứ Sáu, không phải hoàn phí năm hay học môn khác.", "B": "Không phù hợp với dẫn chứng: Thẻ thành viên mới. No additional charge nghĩa là không tính thêm phí cho buổi bù thứ Sáu, không phải hoàn phí năm hay học môn khác.", "C": "Không phù hợp với dẫn chứng: Hoàn phí cả năm. No additional charge nghĩa là không tính thêm phí cho buổi bù thứ Sáu, không phải hoàn phí năm hay học môn khác.", "D": "Không phù hợp với dẫn chứng: Buổi quần vợt riêng. No additional charge nghĩa là không tính thêm phí cho buổi bù thứ Sáu, không phải hoàn phí năm hay học môn khác."}}',161 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND question_text='What is offered to Tuesday swimming students?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l1%' ORDER BY id LIMIT 1));
