INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1),'{"title": "Career Fair Invitation", "glossary": {"admission": "việc vào cửa", "register": "đăng ký", "résumé": "sơ yếu lý lịch; CV", "interviews": "các cuộc phỏng vấn", "limited": "hạn chế"}, "documents": [{"title": "Meet local employers", "title_vi": "Gặp nhà tuyển dụng địa phương", "lines": [{"en": "The Riverside Career Fair takes place at City Hall on October 22 from 10 a.m. to 3 p.m. Admission is free, but visitors must register online by October 18.", "vi": "Hội chợ việc làm Riverside diễn ra tại Tòa thị chính ngày 22 tháng 10 từ 10 giờ sáng đến 3 giờ chiều. Vào cửa miễn phí nhưng khách phải đăng ký trực tuyến trước hạn 18 tháng 10."}, {"en": "Bring several copies of your résumé. Employers will conduct short interviews throughout the day. A résumé review desk will be available from noon. Parking is limited, so visitors are encouraged to use public transport.", "vi": "Hãy mang vài bản CV. Nhà tuyển dụng phỏng vấn ngắn suốt ngày. Bàn góp ý CV mở từ trưa. Chỗ đỗ xe hạn chế nên khách được khuyến khích dùng phương tiện công cộng."}]}], "content_key": "n11-reading-expansion-20261116-p7-l2"}',2 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l2%');
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l2%' ORDER BY id LIMIT 1),'What must visitors do before attending?','{"translation": "Khách phải làm gì trước khi đến?", "options_vi": {"A": "Trả phí vào cửa", "B": "Đặt chỗ đỗ xe", "C": "Đăng ký trực tuyến", "D": "Nộp giấy khám sức khỏe"}, "evidence": "Admission is free, but visitors must register online by October 18.", "explanation": "Yêu cầu bắt buộc là đăng ký trực tuyến; vào cửa miễn phí, không có yêu cầu đặt chỗ xe hoặc giấy khám sức khỏe.", "analysis": {"A": "Không phù hợp với dẫn chứng: Trả phí vào cửa. Yêu cầu bắt buộc là đăng ký trực tuyến; vào cửa miễn phí, không có yêu cầu đặt chỗ xe hoặc giấy khám sức khỏe.", "B": "Không phù hợp với dẫn chứng: Đặt chỗ đỗ xe. Yêu cầu bắt buộc là đăng ký trực tuyến; vào cửa miễn phí, không có yêu cầu đặt chỗ xe hoặc giấy khám sức khỏe.", "C": "Đúng. Yêu cầu bắt buộc là đăng ký trực tuyến; vào cửa miễn phí, không có yêu cầu đặt chỗ xe hoặc giấy khám sức khỏe.", "D": "Không phù hợp với dẫn chứng: Nộp giấy khám sức khỏe. Yêu cầu bắt buộc là đăng ký trực tuyến; vào cửa miễn phí, không có yêu cầu đặt chỗ xe hoặc giấy khám sức khỏe."}}',160 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND question_text='What must visitors do before attending?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l2%' ORDER BY id LIMIT 1));
