INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l2%' ORDER BY id LIMIT 1),'Why is public transport recommended?','{"translation": "Vì sao nên dùng phương tiện công cộng?", "options_vi": {"A": "Tòa thị chính cấm ô tô", "B": "Chỗ đỗ xe hạn chế", "C": "Vé xe buýt miễn phí", "D": "Phỏng vấn trên xe buýt"}, "evidence": "Parking is limited, so visitors are encouraged to use public transport.", "explanation": "Thông báo đưa ra lý do thiếu chỗ đỗ xe, không nói cấm xe, miễn phí vé hoặc phỏng vấn trên xe.", "analysis": {"A": "Không phù hợp với dẫn chứng: Tòa thị chính cấm ô tô. Thông báo đưa ra lý do thiếu chỗ đỗ xe, không nói cấm xe, miễn phí vé hoặc phỏng vấn trên xe.", "B": "Đúng. Thông báo đưa ra lý do thiếu chỗ đỗ xe, không nói cấm xe, miễn phí vé hoặc phỏng vấn trên xe.", "C": "Không phù hợp với dẫn chứng: Vé xe buýt miễn phí. Thông báo đưa ra lý do thiếu chỗ đỗ xe, không nói cấm xe, miễn phí vé hoặc phỏng vấn trên xe.", "D": "Không phù hợp với dẫn chứng: Phỏng vấn trên xe buýt. Thông báo đưa ra lý do thiếu chỗ đỗ xe, không nói cấm xe, miễn phí vé hoặc phỏng vấn trên xe."}}',162 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND question_text='Why is public transport recommended?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l2%' ORDER BY id LIMIT 1));
