INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1),'{"title": "Catering Adjustment", "glossary": {"amend": "sửa đổi", "vegetarian": "chay", "preference": "sở thích; lựa chọn", "confirmation": "xác nhận", "meals": "suất ăn"}, "documents": [{"title": "Catering order", "title_vi": "Đơn đặt tiệc", "lines": [{"en": "Order C315 · Event: Staff seminar on March 14 · Lunch boxes: 24 standard and 6 vegetarian · Delivery: 11:30 a.m. · Price: $12 per box", "vi": "Đơn C315 · Sự kiện: Hội thảo nhân viên ngày 14 tháng 3 · Hộp ăn: 24 thường và 6 chay · Giao: 11 giờ 30 · Giá: 12 đô la mỗi hộp"}]}, {"title": "Customer email", "title_vi": "Email khách hàng", "lines": [{"en": "Please amend order C315. Four guests have changed their preference from standard to vegetarian meals. The total number of meals and delivery time should remain the same. Please send an updated confirmation.", "vi": "Vui lòng sửa đơn C315. Bốn khách đổi từ suất thường sang suất chay. Tổng số suất và giờ giao giữ nguyên. Vui lòng gửi xác nhận cập nhật."}]}], "content_key": "n11-reading-expansion-20261116-p7-l3"}',2 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l3%');
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l3%' ORDER BY id LIMIT 1),'How many vegetarian lunches are now needed?','{"translation": "Hiện cần bao nhiêu suất chay?", "options_vi": {"A": "4", "B": "6", "C": "10", "D": "30"}, "evidence": "6 vegetarian. / Four guests have changed their preference from standard to vegetarian meals.", "explanation": "Ban đầu 6 suất chay, thêm 4 chuyển từ suất thường, tổng 10. Tổng số khách vẫn 30.", "analysis": {"A": "Không phù hợp với dẫn chứng: 4. Ban đầu 6 suất chay, thêm 4 chuyển từ suất thường, tổng 10. Tổng số khách vẫn 30.", "B": "Không phù hợp với dẫn chứng: 6. Ban đầu 6 suất chay, thêm 4 chuyển từ suất thường, tổng 10. Tổng số khách vẫn 30.", "C": "Đúng. Ban đầu 6 suất chay, thêm 4 chuyển từ suất thường, tổng 10. Tổng số khách vẫn 30.", "D": "Không phù hợp với dẫn chứng: 30. Ban đầu 6 suất chay, thêm 4 chuyển từ suất thường, tổng 10. Tổng số khách vẫn 30."}}',160 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND question_text='How many vegetarian lunches are now needed?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l3%' ORDER BY id LIMIT 1));
