INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l3%' ORDER BY id LIMIT 1),'What is the total cost of the revised order?','{"translation": "Tổng tiền đơn sửa đổi là bao nhiêu?", "options_vi": {"A": "120 đô la", "B": "288 đô la", "C": "312 đô la", "D": "360 đô la"}, "evidence": "Lunch boxes: 24 standard and 6 vegetarian. / Price: $12 per box. / The total number of meals ... should remain the same.", "explanation": "Số suất vẫn 24 + 6 = 30, mỗi suất 12 đô la, tổng 360 đô la; đổi loại suất không đổi giá.", "analysis": {"A": "Không phù hợp với dẫn chứng: 120 đô la. Số suất vẫn 24 + 6 = 30, mỗi suất 12 đô la, tổng 360 đô la; đổi loại suất không đổi giá.", "B": "Không phù hợp với dẫn chứng: 288 đô la. Số suất vẫn 24 + 6 = 30, mỗi suất 12 đô la, tổng 360 đô la; đổi loại suất không đổi giá.", "C": "Không phù hợp với dẫn chứng: 312 đô la. Số suất vẫn 24 + 6 = 30, mỗi suất 12 đô la, tổng 360 đô la; đổi loại suất không đổi giá.", "D": "Đúng. Số suất vẫn 24 + 6 = 30, mỗi suất 12 đô la, tổng 360 đô la; đổi loại suất không đổi giá."}}',161 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND question_text='What is the total cost of the revised order?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l3%' ORDER BY id LIMIT 1));
