INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l3%' ORDER BY id LIMIT 1),'What does the customer ask the caterer to send?','{"translation": "Khách yêu cầu nhà cung cấp gửi gì?", "options_vi": {"A": "Xác nhận cập nhật", "B": "Danh sách nhân viên mới", "C": "Khoản hoàn phí giao", "D": "Công thức món chay"}, "evidence": "Please send an updated confirmation.", "explanation": "Khách muốn xác nhận lại đơn đã sửa, không hỏi danh sách người, hoàn phí hay công thức.", "analysis": {"A": "Đúng. Khách muốn xác nhận lại đơn đã sửa, không hỏi danh sách người, hoàn phí hay công thức.", "B": "Không phù hợp với dẫn chứng: Danh sách nhân viên mới. Khách muốn xác nhận lại đơn đã sửa, không hỏi danh sách người, hoàn phí hay công thức.", "C": "Không phù hợp với dẫn chứng: Khoản hoàn phí giao. Khách muốn xác nhận lại đơn đã sửa, không hỏi danh sách người, hoàn phí hay công thức.", "D": "Không phù hợp với dẫn chứng: Công thức món chay. Khách muốn xác nhận lại đơn đã sửa, không hỏi danh sách người, hoàn phí hay công thức."}}',162 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND question_text='What does the customer ask the caterer to send?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-2026111