INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1),'{"title": "Printer Service Agreement", "glossary": {"quarter": "quý (ba tháng)", "technician": "kỹ thuật viên", "replacement": "thay thế", "billed": "được tính tiền", "recurring": "tái diễn"}, "documents": [{"title": "Service plan summary", "title_vi": "Tóm tắt gói dịch vụ", "lines": [{"en": "The OfficeCare plan costs $60 per month and includes two technician visits per quarter. Additional visits cost $45 each. Replacement parts are billed separately. Support is available Monday through Friday, 8 a.m. to 6 p.m.", "vi": "Gói OfficeCare giá 60 đô la mỗi tháng, gồm hai lần kỹ thuật viên đến mỗi quý. Mỗi lần thêm giá 45 đô la. Linh kiện thay tính riêng. Hỗ trợ thứ Hai đến thứ Sáu, 8 giờ sáng đến 6 giờ chiều."}]}, {"title": "Service record and request", "title_vi": "Lịch sử và yêu cầu dịch vụ", "lines": [{"en": "Our printer was serviced on January 9 and February 12 under OfficeCare. It has stopped printing again. Please arrange another visit on March 20. We do not expect any parts to be replaced.", "vi": "Máy in được bảo dưỡng ngày 9 tháng 1 và 12 tháng 2 theo OfficeCare. Máy lại ngừng in. Vui lòng bố trí một lần nữa ngày 20 tháng 3. Chúng tôi dự kiến không cần thay linh kiện."}]}], "content_key": "n11-reading-expansion-20261116-p7-l4"}',2 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l4%');
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l4%' ORDER BY id LIMIT 1),'What extra visit charge should the customer expect on March 20?','{"translation": "Khách dự kiến chịu phí lần đến thêm nào ngày 20 tháng 3?", "options_vi": {"A": "0 đô la", "B": "45 đô la", "C": "60 đô la", "D": "90 đô la"}, "evidence": "Two technician visits per quarter. Additional visits cost $45 each. / January 9 and February 12 ... another visit on March 20.", "explanation": "Tháng 1, 2, 3 cùng một quý. Hai lượt miễn phí trong gói đã dùng, lượt thứ ba thêm 45 đô la.", "analysis": {"A": "Không phù hợp với dẫn chứng: 0 đô la. Tháng 1, 2, 3 cùng một quý. Hai lượt miễn phí trong gói đã dùng, lượt thứ ba thêm 45 đô la.", "B": "Đúng. Tháng 1, 2, 3 cùng một quý. Hai lượt miễn phí trong gói đã dùng, lượt thứ ba thêm 45 đô la.", "C": "Không phù hợp với dẫn chứng: 60 đô la. Tháng 1, 2, 3 cùng một quý. Hai lượt miễn phí trong gói đã dùng, lượt thứ ba thêm 45 đô la.", "D": "Không phù hợp với dẫn chứng: 90 đô la. Tháng 1, 2, 3 cùng một quý. Hai lượt miễn phí trong gói đã dùng, lượt thứ ba thêm 45 đô la."}}',160 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND question_text='What extra visit charge should the customer expect on March 20?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l4%' ORDER BY id LIMIT 1));
