INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l4%' ORDER BY id LIMIT 1),'The word “billed” is closest in meaning to','{"translation": "Từ billed gần nghĩa nhất với", "options_vi": {"A": "được sửa", "B": "được giao", "C": "được tái chế", "D": "được tính tiền"}, "evidence": "Replacement parts are billed separately.", "explanation": "Trong ngữ cảnh chi phí, billed nghĩa là charged: được tính tiền riêng.", "analysis": {"A": "Không phù hợp với dẫn chứng: được sửa. Trong ngữ cảnh chi phí, billed nghĩa là charged: được tính tiền riêng.", "B": "Không phù hợp với dẫn chứng: được giao. Trong ngữ cảnh chi phí, billed nghĩa là charged: được tính tiền riêng.", "C": "Không phù hợp với dẫn chứng: được tái chế. Trong ngữ cảnh chi phí, billed nghĩa là charged: được tính tiền riêng.", "D": "Đúng. Trong ngữ cảnh chi phí, billed nghĩa là charged: được tính tiền riêng."}}',163 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND question_text='The word “billed” is closest in meaning to' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l4%' ORDER BY id LIMIT 1));
