INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1),'{"title": "Training Venue Decision", "glossary": {"venue": "địa điểm tổ chức", "capacity": "sức chứa", "projector": "máy chiếu", "presenter": "diễn giả", "remaining": "còn lại", "satisfies": "đáp ứng"}, "documents": [{"title": "Event requirements", "title_vi": "Yêu cầu sự kiện", "lines": [{"en": "We need a venue for 50 people on December 6. The room must be available from 8 a.m. to 5 p.m. and include a projector. The total room and catering budget is $2,000.", "vi": "Cần địa điểm cho 50 người ngày 6 tháng 12. Phòng phải dùng được từ 8 giờ sáng đến 5 giờ chiều và có máy chiếu. Tổng ngân sách phòng và ăn uống là 2.000 đô la."}]}, {"title": "Venue quotations", "title_vi": "Báo giá địa điểm", "lines": [{"en": "Maple Center: capacity 60; room $900; projector included; lunch $18 per person; available 9 a.m.–6 p.m. Cedar House: capacity 50; room $1,100; projector included; lunch $16 per person; available 8 a.m.–5 p.m.", "vi": "Maple Center: sức chứa 60; phòng 900 đô la; gồm máy chiếu; ăn trưa 18 đô la mỗi người; dùng 9 giờ sáng–6 giờ chiều. Cedar House: sức chứa 50; phòng 1.100 đô la; gồm máy chiếu; ăn trưa 16 đô la mỗi người; dùng 8 giờ sáng–5 giờ chiều."}]}, {"title": "Organizer’s decision", "title_vi": "Quyết định của ban tổ chức", "lines": [{"en": "The start time cannot be changed because our presenter has an afternoon flight. Select the venue that satisfies every requirement. Spend any remaining budget on notebooks costing $2 each.", "vi": "Không thể đổi giờ bắt đầu vì diễn giả có chuyến bay buổi chiều. Chọn nơi đáp ứng mọi yêu cầu. Dùng ngân sách còn lại mua sổ giá 2 đô la mỗi quyển."}]}], "content_key": "n11-reading-expansion-20261116-p7-l5"}',2 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l5%');
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l5%' ORDER BY id LIMIT 1),'Which venue meets every requirement?','{"translation": "Địa điểm nào đạt mọi yêu cầu?", "options_vi": {"A": "Chỉ Maple Center", "B": "Cả hai", "C": "Chỉ Cedar House", "D": "Không nơi nào"}, "evidence": "The room must be available from 8 a.m. to 5 p.m. / Cedar House ... available 8 a.m.–5 p.m.", "explanation": "Cedar đáp ứng giờ, 50 chỗ, máy chiếu, và tổng 1.900 đô la trong ngân sách. Maple chỉ mở từ 9 giờ.", "analysis": {"A": "Không phù hợp với dẫn chứng: Chỉ Maple Center. Cedar đáp ứng giờ, 50 chỗ, máy chiếu, và tổng 1.900 đô la trong ngân sách. Maple chỉ mở từ 9 giờ.", "B": "Không phù hợp với dẫn chứng: Cả hai. Cedar đáp ứng giờ, 50 chỗ, máy chiếu, và tổng 1.900 đô la trong ngân sách. Maple chỉ mở từ 9 giờ.", "C": "Đúng. Cedar đáp ứng giờ, 50 chỗ, máy chiếu, và tổng 1.900 đô la trong ngân sách. Maple chỉ mở từ 9 giờ.", "D": "Không phù hợp với dẫn chứng: Không nơi nào. Cedar đáp ứng giờ, 50 chỗ, máy chiếu, và tổng 1.900 đô la trong ngân sách. Maple chỉ mở từ 9 giờ."}}',160 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND question_text='Which venue meets every requirement?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l5%' ORDER BY id LIMIT 1));
