INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l5%' ORDER BY id LIMIT 1),'Why is Maple Center unsuitable?','{"translation": "Vì sao Maple không phù hợp?", "options_vi": {"A": "Mở cửa quá muộn", "B": "Sức chứa quá nhỏ", "C": "Không có máy chiếu", "D": "Tiền ăn vượt toàn bộ ngân sách"}, "evidence": "Maple Center ... available 9 a.m.–6 p.m. / The start time cannot be changed.", "explanation": "Sự kiện cần bắt đầu 8 giờ, nhưng Maple chỉ cho dùng từ 9 giờ. Sức chứa và máy chiếu đều đạt.", "analysis": {"A": "Đúng. Sự kiện cần bắt đầu 8 giờ, nhưng Maple chỉ cho dùng từ 9 giờ. Sức chứa và máy chiếu đều đạt.", "B": "Không phù hợp với dẫn chứng: Sức chứa quá nhỏ. Sự kiện cần bắt đầu 8 giờ, nhưng Maple chỉ cho dùng từ 9 giờ. Sức chứa và máy chiếu đều đạt.", "C": "Không phù hợp với dẫn chứng: Không có máy chiếu. Sự kiện cần bắt đầu 8 giờ, nhưng Maple chỉ cho dùng từ 9 giờ. Sức chứa và máy chiếu đều đạt.", "D": "Không phù hợp với dẫn chứng: Tiền ăn vượt toàn bộ ngân sách. Sự kiện cần bắt đầu 8 giờ, nhưng Maple chỉ cho dùng từ 9 giờ. Sức chứa và máy chiếu đều đạt."}}',161 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND question_text='Why is Maple Center unsuitable?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l5%' ORDER BY id LIMIT 1));
