INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l5%' ORDER BY id LIMIT 1),'What is the room and lunch cost at the selected venue?','{"translation": "Tiền phòng và ăn tại nơi được chọn là bao nhiêu?", "options_vi": {"A": "1.100 đô la", "B": "1.800 đô la", "C": "2.000 đô la", "D": "1.900 đô la"}, "evidence": "Cedar House ... room $1,100 ... lunch $16 per person. / 50 people.", "explanation": "Phòng 1.100 cộng 50 × 16 = 800 tiền ăn, tổng 1.900 đô la.", "analysis": {"A": "Không phù hợp với dẫn chứng: 1.100 đô la. Phòng 1.100 cộng 50 × 16 = 800 tiền ăn, tổng 1.900 đô la.", "B": "Không phù hợp với dẫn chứng: 1.800 đô la. Phòng 1.100 cộng 50 × 16 = 800 tiền ăn, tổng 1.900 đô la.", "C": "Không phù hợp với dẫn chứng: 2.000 đô la. Phòng 1.100 cộng 50 × 16 = 800 tiền ăn, tổng 1.900 đô la.", "D": "Đúng. Phòng 1.100 cộng 50 × 16 = 800 tiền ăn, tổng 1.900 đô la."}}',162 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND question_text='What is the room and lunch cost at the selected venue?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l5%' ORDER BY id LIMIT 1));
