INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l5%' ORDER BY id LIMIT 1),'How many notebooks can be purchased with the remaining budget?','{"translation": "Có thể mua bao nhiêu sổ bằng tiền còn lại?", "options_vi": {"A": "25", "B": "50", "C": "100", "D": "200"}, "evidence": "The total ... budget is $2,000. / Notebooks costing $2 each.", "explanation": "Sau 1.900 tiền phòng và ăn, còn 100 đô la. Mỗi sổ 2 đô la nên mua được 50 quyển.", "analysis": {"A": "Không phù hợp với dẫn chứng: 25. Sau 1.900 tiền phòng và ăn, còn 100 đô la. Mỗi sổ 2 đô la nên mua được 50 quyển.", "B": "Đúng. Sau 1.900 tiền phòng và ăn, còn 100 đô la. Mỗi sổ 2 đô la nên mua được 50 quyển.", "C": "Không phù hợp với dẫn chứng: 100. Sau 1.900 tiền phòng và ăn, còn 100 đô la. Mỗi sổ 2 đô la nên mua được 50 quyển.", "D": "Không phù hợp với dẫn chứng: 200. Sau 1.900 tiền phòng và ăn, còn 100 đô la. Mỗi sổ 2 đô la nên mua được 50 quyển."}}',163 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND question_text='How many notebooks can be purchased with the remaining budget?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l5%' ORDER BY id LIMIT 1));
