INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l5%' ORDER BY id LIMIT 1),'Why must the original start time be kept?','{"translation": "Vì sao phải giữ giờ bắt đầu ban đầu?", "options_vi": {"A": "Ăn trưa lúc 8 giờ sáng", "B": "Phòng cần vệ sinh", "C": "Diễn giả có chuyến bay sau đó", "D": "Sổ đến sớm"}, "evidence": "The start time cannot be changed because our presenter has an afternoon flight.", "explanation": "Lịch bay buổi chiều của diễn giả là lý do trực tiếp; các lý do khác không xuất hiện trong email.", "analysis": {"A": "Không phù hợp với dẫn chứng: Ăn trưa lúc 8 giờ sáng. Lịch bay buổi chiều của diễn giả là lý do trực tiếp; các lý do khác không xuất hiện trong email.", "B": "Không phù hợp với dẫn chứng: Phòng cần vệ sinh. Lịch bay buổi chiều của diễn giả là lý do trực tiếp; các lý do khác không xuất hiện trong email.", "C": "Đúng. Lịch bay buổi chiều của diễn giả là lý do trực tiếp; các lý do khác không xuất hiện trong email.", "D": "Không phù hợp với dẫn chứng: Sổ đến sớm. Lịch bay buổi chiều của diễn giả là lý do trực tiếp; các lý do khác không xuất hiện trong email."}}',164 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND question_text='Why must the original start time be kept?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l5%' ORDER BY id LIMIT 1));
